      "stage": "初中",
      "audioCloudPath": "_content/listening-em2/audio/sh-em2-2021-闵行-listening.mp3",
      "transcript": "参考答案were even happier than the others；brought the lot to life again with their own hands。 VII. Writing（作文）（20分） 84. Write at least 60 words on the topic “My funnest family memory”（根据提示，以“我最有趣的家庭回忆”为题，写一篇不少于60个词的短文，标点符号不占格。） 提示：回忆有趣的家庭生活总是美好的。请结合你的亲身经历，描述你和家人在一起时最有趣的事儿，并谈谈感想。 （注意：文中不得出现考生的姓名、校名及其它相关信息，否则不予评分。抄袭阅读理解语篇的不给分。） ____________________________________________________________________________________________________________________________________________________________________________________________________________________________________________________________________________________________________________________________________________________________________________________________________________________________________________________________________________________________________________________________________________________________________________________________________________________________________________________________________ ____________________________________________________________________________________________ 【答案】 范文： My funnest family memory There are countless interesting things in our family. Let me tell you one thing. It’s about eating. I remember once again, when I was at my grandma’s house, it was going to a dinner. My stomach was hungry and sang “I want to eat”. I ran to the table in a windy manner and started eating. I just had a bite of the food, feeling very spicy, asked her mother, “Mom, why is vegetable pepper so hot?” Mom ran over and tasted vegetable pepper and said, “This is not vegetable pepper, it’s pepper!” “Ah?” I asked in confusion. This is chili, no wonder it’s so spicy. “Give me some water!” The family laughed when they heard it. In fact, there are many interesting family stories, waiting for us to discover. As long as you are serious about discovering it, you will feel that family fun everywhere. 【解析】 【详解】 1. 题干解读：这篇作文要求我们以“我最有趣的家庭回忆”为题，根据写作提示，谈一谈自己最有趣的家庭回忆，属于话题作文。 2. 写作指导：审题可知，这篇短文应以第一人称和一般过去时为主来叙述，要写出家庭生活的有趣及自己的感受，注意主谓一致，保证无语法和单词拼写错误。 附听力原文： A. Listen and choose the right picture（根据你听到的内容，选出相应的图片，每个句子念两遍。） 1. The sign tells us to wash our hands regularly. (C) 2. Eddie is cleaning the table carefully, isn’t he? (D) 3. It is convenient for people to attend online meetings at home. (A) 4. My family watched the lantern show during the Spring Festival. (B) 5. Grandma Liang is an active member of the dancing group in our neighborhood. (E) B. Listen to the dialogue and choose the best answer to the question you hear（根据你听到的对话和问题，选出最恰当的答案，对话和问题都念两遍。） 6. M: Would you like a cup of tea or coffee? W: Neither. A glass of water please. Q: What will the woman drink? (B) 7. M: Was it hot here last summer? W: Yes, it was. August was much hotter than June and July. Q: Which was the hottest month here last year? (C) 8. W: Tomorrow is the Open Day. Are there enough chairs for the parents’ meeting? M: Yes. I’ve prepared thirty. W: I’m afraid we need five more. Q: How many parents will probably come to the Open Day tomorrow? (C) 9. W: Why don’t you go to bed, Bob? It’s really late. M: I have to finish this report. The professor will need it tomorrow. W: Don’t stay up too late. Q: What’s the possible relationship between the two speakers? (A) 10. M: Where did your family have dinner yesterday? W: We went to a seafood restaurant in a shopping mall. M: What did you think of the food there? W: Oh, terrible. We will never go there again. Q: What can we learn from the dialogue? (D) C. Listen to the passage and tell whether the following statements are true or false（判断下列句子是否符合你听到的内容，符合的用“T”表示，不符合的用“F”表示，短文念两遍。） Mrs. Brown had just finished cooking when she heard a knock at the door. She was surprised because the postman and the milkman had already been there, and she wasn’t expecting any visitors. She went into the front room, pulled the curtain back a little, and looked out of the window to see who it was. A man was standing on the steps leading to the front door. He was a tall man wearing a big black hat pulled forward over his eyes, so it was difficult to see his face clearly. His shoes were old and dirty. He carried a small black bag in his hand. As she looked at him, Mrs. Brown remembered something she had read in the newspapers about old ladies who opened the doors to strangers, and were hit on the head and had their things stolen. She felt frightened and decided not to open the door. She let the curtain fall back and waited. The man looked round quickly, put his hand in his pocket, took out some keys and began to try them one by one in the front door. As soon as Mrs. Brown saw this, she picked up the phone quietly and dialed 911. D. Listen to the passage and complete the following sentences（听短文，完成下列内容，每空格限填一词，短文念两遍。） In science fiction films, we often see machines doing jobs that humans usually do. This is gradually coming true. By 2025, machines will do more work than humans, according to a new report. The report says that in the next five years, machines will take up about 85 million jobs. This means that machines will deal with about half of all work tasks, almost twice as many as now. These jobs include factory workers, accountants and mechanics. But people don’t need to be worried about the situation. The report also shows that at the same time, 97 million new jobs will be created. New industries will be created as the society changes and develops. At present, countries around the world are focusing on areas like environmental protection, AI development and elderly care. These jobs need human skills such as advising, decision-making, reasoning and communicating. The report points out that people need to learn new skills to deal with the change of the society.",
