      "transcript": "Part 1 Listening 第一部分 听力 I. Listening Comprehension A. Listen and choose the right picture (根据你听到的内容，选出相应的图片) 1. Little Alice is helping her mum wash dishes in the kitchen. (C) 2. My father’s job is to put out fire and save people’s lives. (B) 3. The smoke from the factory is harmful and it makes us feel sick. (E) 4. Tom’s aunt asked him to paint the fence before she came back. (D) 5. The film star was interviewed by a newspaper reporter just now. (A) B. Listen to the dialogue and choose the best answer to the question you hear (根据你听到的对话和问题，选出最恰当的答案) 6. W: Sam, what’s your hobby? M: Playing ball games with my friends. What about you, Susan? W: I like collecting stamps. It’s interesting. Q: What’s Sam’s hobby? (B) 7. M: I have an interview at 9:30. I have to leave now. W: Don’t hurry. There is still 30 minutes left. Q: What time is it now? (C) 8. M: Excuse me, how much is this pair of shoes? W: It was one hundred and eighty yuan a pair last week, but now it’s only one hundred and twenty yuan. M: Great, I’ll take the white pair. Q: How much is the pair of shoes now? (C) 9. W: Johnny, you look worried. What happened? M: Oh, I missed the train. I started very early this morning, but I was still late. W: How did it happen? M: I didn’t know the traffic was so heavy. Q: Why didn’t the man catch the train? (D) 10. W: Look, there’s a new type of digital camera. Shall we buy one? M: It looks very nice. How much is it? W: Six thousand yuan. M: It sounds like a waste of money. We seldom go out for sightseeing. Q: What can we learn from the dialogue? (D) C. Listen to the dialogue and tell whether the following statements are true or false. (判断下列句子是否符合你听到的内容, 符合的用“T”表示，不符合的用“F”表示) M: Hello! May I speak to Alice? W: Hello, this is Alice. Who’s calling? M: Hi, Alice. This is Peter. We haven’t seen each other for two weeks. Did you enjoy your holiday in the country? W: Yes, thanks. We had a great time. And some friends went with me. M: Where did you stay? In a hotel? W: We stayed in a hotel for only one day. For the other days we camped in the mountain, near Snow Town. We cooked our meals on an open fire and ate outside. M: Sounds wonderful. Was the weather good? W: It shone brightly almost every day and it didn’t rain even once. M: Did you like the people there? W: Yes, they were great and friendly. We met some farmers and I had tea in their houses. M: When did you go back? Last night? W: No. we came back this morning. I got up at 4:30, left at 5:00 and arrived here at 9:00. I am so tired. M: You really had a pleasant holiday. Now, you need a good rest. 11. T 12. F 13. F 14. T 15. F D. Listen to the passage and complete the following sentences (听短文，完成下列内容。每空格限填一词) Never try to work when you are very hungry. If you decide to do your homework right after school, you may get something to eat before you get to work. Always do your homework before you get too tired. Don’t wait until very late in the evening, or your work will seem much harder than it really is. If you have more than an hour’s work, give yourself a break after an hour. On the other hand, don’t break it up so much that you can’t get anything done, and you should be able to work at least a half at a time without stopping. Don’t put it off until last minute. If you put off doing your homework, you will have it on your mind, and you won’t enjoy your free time so much. If you put it off until the end of the week or until right before a test, you will have too much catching up to do. A little bit each night, enough to keep up with what is happening each day in school, will take the fear out of tests and keep you on top of it. Do your homework at the same time every evening. This will help you make it a good habit. It will make your homework easier to do, and it will make your free time more enjoyable as well. 16. too tired 17. a break 18. without stopping 19. put off 20. good habit",
      "hasAudio": true,
