      "transcript": "参考答案 A. Listen and choose the right picture (根据你听到的内容，选出相应的图片) （共5分） Jimmy does morning exercise every day to keep healthy. ( C ) Visitors in Starfish Hotel can enjoy a great view of the sea. ( F ) It’s a fine spring day and the Chen family is planting a tree. ( D ) The old lady started learning painting after she retired last year. ( E ) Sitting around to make tea is popular with many young people. ( B ) 答案：1. C 2.F 3.D 4.E 5.B B. Listen to the dialogues and choose the best answer to each question your hear (根据你听到的对话和问题，选出最恰当的答案) （共5分） 6. W: I need to get a birthday present for my Dad. Any suggestions? M: How about a scarf or a smart watch? W: A smart watch is a good choice. Q: What will the woman buy for her Dad? ( C ) 7. M: Hi, Sarah! Are you going to the drama show this Tuesday? W: As far as I know, the show will be delayed to Thursday. Q: When will Sarah go to the drama show? ( A ) M: Honey, what shall we do after work? W: How about doing some shopping? M: I don’t feel like that. Let’s watch a hit movie! W: Sounds great! Q: Where will the couple go after work? ( B ) W: How long have you had a sore throat? M: Almost a week. W: I see. Do a blood test first and come to me when you get the result. Q: Who might the two speakers be? ( C ) M: You know, Alice, it’s sometimes difficult to help my son with his homework. W: Sorry to hear that, Tom. To be honest, I am also in the same situation as you. Q: What can we learn from the dialogue? ( D ) 答案：6. C 7.A 8.B 9.C 10. D C. Listen to the passage and tell whether the following statements are true or false (判断下列句子是否符合你听到的短文内容，符合的用“T”表示，不符合的用“F”表示)（共5分） When the class teacher said there would be an educational visit to a local history museum, Jack jumped for joy. On that day, Jack and his classmates took a bus to the museum. As they arrived, they were welcomed by a friendly guide who showed them around. The guide introduced them to many things, such as old tools, clothes, and even toys. Jack’s favorite exhibit was a collection of old coins. The guide told them what the coins stood for and what they were used for. As they walked around, Jack couldn’t help but ask questions. He was curious about everything, and the guide was more than happy to answer his questions. Other students also started asking questions after Jack. At the end of the visit, Jack thought that history wasn’t a boring subject in school but an interesting one. From then on, Jack became interested in history. He was thankful for the educational visit, and it had inspired him to keep learning about the past and how it shaped the world today. 答案：11. T 12. F 13. T 14. F 15. T Listen to the dialogue and complete the following sentences (听对话，用听到的单词完成下列句子。每空格限填一词) （共10分） Sandy and Billy are university students and they are talking about online courses. Sandy: Hey, Billy, have you heard of Lynda? Billy: Is that a person? Sandy: No. It’s a website. Billy: Don't know it. Could you tell me more about it? Sandy: Basically, it has a number of online courses. You can learn almost anything. Billy: Oh, interesting. Have you tried it, Sandy? Sandy: Yeah, I’ve been taking an online course on programming in my spare time. Billy: Nice! I've been thinking about trying to learn public speech. Is it free or what? Sandy: No, it costs. I paid for the course on Lynda and it was like 50 dollars or something. Not too expensive. Billy: That sounds reasonable. How’s the quality? Sandy: For 50 dollars, it’s really worth it. It’s a great way to learn new skills and keep up with the times. And there are reviews you can check out. Billy: Ah, I see. Maybe it’s a good way. Sandy: Sure. Besides, you can learn and go over it at your own speed, which is really convenient. Billy: That makes sense. I will give it a try. Thanks for the recommendation! 答案：16. a website 17. public speech 18. 50/fifty dollars 19. new skills 20. go over",
      "hasAudio": true,
