      "audioCloudPath": "_content/listening-em2/audio/sh-em2-2025-嘉定-listening.mp3",
      "transcript": "参考答案 Part 1 A. Listen and choose the right picture (根据你听到的内容，选出相应的图片) （5 分） 1. Li Ming went to the city park and planted several trees with his friends. (F) 2. Students are now learning Tai Chi as part of their PE class this year. (A). 3. Jenny is conducting a survey with her classmates about their favorite food. (E) 4. Do you know the kite has been a part of Chinese culture for over 2000 years？ (D) 5. Teens can explore the wild and make friends when they go camping. (B) B. Listen to the dialogue and choose the best answer to the question you hear (根据你听到的 对话和问题，选出最恰当的答案) （5 分） 6. M: Why are you in such a hurry, Miss Gu? W: I’ll fly to Guangzhou this evening. I must get everything ready before 4 o’clock. Q: How will Miss Gu go to Guangzhou? (B) 7. M: I hope it will be fine tomorrow. I’m going hiking with Mary. W: I think it will be fine. I got it from the TV programme. Q: What are the two speakers talking about? (C) 8. M: Excuse me, can I pack the steak left on my plate? W: Oh, no problem, sir. Just wait a minute, and I’ll get you a packing box and a bag right away. Q: Where does this conversation most probably take place? (D) 9. M: Customer Service. May I help you? W: Yes, I bought a red skirt, but you delivered a white one. M: Oh, I’m terribly sorry, madam. Please return it to us. We will pay for the delivery and send you the correct colour. Q: Why does the man say sorry? (A) 10. M: Our wild life protection group is looking for new members to join. I thought you might be interested. W: Oh, I’d love to. But I have already signed up for the Stem club. I want to improve my programming skills this term. The activities take up most of my spare time every week. Q: What does the woman mean? (B) 第 1 页 共 5 页 {#{QQABDYKo4gI4kNTACI5KA0VoCkoYkIIiJOgMhUCRuA4LSJNIBIA=}#} C. Listen to the passage and tell whether the following statements are true or false (判断下列 句子是否符合你听到的短文内容, 符合的用“T”表示，不符合的用“F”表示) （5 分） (Cindy is traveling in Jamaica. She leaves a voice message to her friend Sherry on her mobile phone to share the experience.) “Hey Sherry, it’s Cindy! I’m having a study trip in Jamaica right now. Yes, the island with those beautiful golden beaches and amazing African drum music. The weather is just perfect, sunny and warm every day. I’m here with my cousins. We’ve been here for three days, but we’ve already done so much! We went on a short river tour, walked along the beach, and yesterday, Oh my gosh—we went to an amazing beach party! So much fun! Local food here’s so delicious! But, we haven’t tried the famous Blue Mountain coffee yet. That’s next on our list. We’ve also made some new friends. They told us the country’s name means “land of wood and water.” and people have lived here for over 2,500 years.” Now you can feel the mix of European, African, and local culture everywhere. Just this morning, we heard some street musicians playing drums and guitars!” The best part is coming up tomorrow. I’m joining a volunteer programme to help look after wounded sea animals! I’ve just got my plan, and since I’ve never done anything like this before, I’m super excited. This trip is not just a holiday, but also an eye-opening experience. 11.T 12. F 13. T 14. T 15. F D. Listen to the dialogue and complete the sentences (听短文，用听到的单词完成句子 。每 空格限填一词) （10 分） W: Good morning, Mr. Fang. May I ask you a few questions about the new break policy? M: Sure, go ahead. W: Your school is trying out longer breaks this term, extending the break time between classes from 10 minutes to 15 minutes. What changes do you see in students? M: Oh, More students go out of the classroom now! They can have more time to rest, to play games and share joy with their friends.They look very happy every break. W: Then what activities do students like most during the break? M: Most students love ball games, like basketball and table tennis. Some younger students like to play skipping rope. They all have great fun! W: Safety is very important for students. What do you do to help them keep safe? M: We teachers walk around the activity areas every break. Students are told to follow the rules. We also teach them to do simple arm exercises instead . W: Hmm, What do you do to help students get ready for class quickly after the break? M: We play soft music for 2 minutes before the break ends. It tells students to finish their games and walk back to the classroom. 第 2 页 共 5 页 {#{QQABDYKo4gI4kNTACI5KA0VoCkoYkIIiJOgMhUCRuA4LSJNIBIA=}#} W: Why do your school make this change? M: We care about the kids’ well-being and growth. The 15-minute break helps them feel relaxed and get ready to learn, and it really makes a real difference. W: I see. That sounds like a thoughtful change. 16. trying out 17. share joy 18. keep safe 19. soft music 20. real difference",
      "hasAudio": true,
